const body = $input.item.json.body;

const event   = body.event;
const meta    = body.pool_metadata || {};
const match   = body.match || {};
const pool    = body.pool || {};
const tip     = body.tip || {};
const ranking = body.ranking || [];

const poolName =
  meta.bolao_nome ||
  meta.pool_name ||
  pool.name ||
  'Bolão';

const inviteLink =
  meta.bolao_convite ||
  meta.invite_link ||
  '';

const footer = [
  `🏆 *${poolName}*`,
  inviteLink ? `🔗 ${inviteLink}` : null
].filter(Boolean).join('\n');

const medals = { 1: '🥇', 2: '🥈', 3: '🥉' };

function formatRanking(list) {
  if (!list || !list.length) return '';
  return list.slice(0, 5).map(p => {
    const prefix = medals[p.rank] || `${p.rank}º`;
    return `${prefix} ${p.user} — ${p.total_points} pts`;
  }).join('\n');
}

function matchResult(m) {
  const h = m.home_score ?? 0;
  const a = m.away_score ?? 0;
  const score = `${m.home_team} *${h}* × *${a}* ${m.away_team}`;
  if (h > a) return `${score}\n🏆 *${m.home_team}* venceu`;
  if (a > h) return `${score}\n🏆 *${m.away_team}* venceu`;
  return `${score}\n🤝 Empate`;
}

let text = '';

switch (event) {
  case 'match.goal':
    text = [
      '⚽ *Gol!*',
      '',
      `${match.home_team} *${match.home_score}* × *${match.away_score}* ${match.away_team}`,
      '',
      footer
    ].join('\n');
    break;

  case 'match.live':
    text = [
      '🏁 *Jogo começou!*',
      '',
      `${match.home_team} × ${match.away_team}`,
      '',
      footer
    ].join('\n');
    break;

  case 'match.finished': {
    const rankLines = formatRanking(ranking);
    text = [
      '🔔 *Jogo encerrado*',
      '',
      matchResult(match),
      '',
      rankLines ? `📊 *Ranking atual*\n${rankLines}` : null,
      '',
      footer
    ].filter(v => v !== null).join('\n');
    break;
  }

  case 'pool.ranking_updated': {
    const rankLines = formatRanking(ranking);
    text = [
      '📊 *Ranking atualizado!*',
      '',
      rankLines || `Líder: *${body.leader || '—'}*`,
      '',
      footer
    ].join('\n');
    break;
  }

  case 'pool.finished':
    text = [
      '🏆 *Bolão encerrado!*',
      '',
      'O torneio chegou ao fim. Confira o resultado final!',
      '',
      footer
    ].join('\n');
    break;

  case 'tip.scored':
    text = [
      '✅ *Palpite pontuado!*',
      '',
      `${tip.user || '—'} → *${tip.points_earned || 0} pts*`,
      '',
      footer
    ].join('\n');
    break;

  case 'pool.daily_matches': {
    const rows = (body.matches || [])
      .map(m => `• ${m.home_team} × ${m.away_team}`)
      .join('\n');

    text = [
      '📅 *Jogos de hoje*',
      '',
      rows || 'Nenhum jogo hoje.',
      '',
      footer
    ].join('\n');
    break;
  }

  default:
    text = [
      `📣 *${event}*`,
      '',
      footer
    ].join('\n');
}

return {
  json: {
    whatsapp_group_id: meta.whatsapp_group_id,
    payload: {
      to: meta.whatsapp_group_id,
      message: text,
      type: 'text'
    }
  }
};

// Salva o payload para combinar com o token depois
const item = $input.first().json;
return [{ json: { payload: item.payload } }];

// Combina o token com o payload salvo anteriormente
const token   = $input.first().json.token;
const payload = $('Merge Payloads').first().json.payload;

return [{ json: { token, payload } }];
